===== policy.ts =====
/** The MHPCO's shared vocabulary for what a policy covers. */

export interface Customer {
  readonly yearsWithMHPCO: number;
}

export interface Item {
  readonly type: string;
  readonly material?: string;
  readonly enchantment?: number;
  readonly cursed?: boolean;
}
===== main-item.ts =====
import type { Item } from "./policy.js";
import type { ItemPricing } from "./premium-contribution.js";
import { NO_PRICING, combinedPricing } from "./premium-contribution.js";
import { basePremiumOf } from "./price-list.js";
import { riskSurchargeOf } from "./risk-surcharge.js";

/**
 * What one main item contributes: the price list's base premium, and the
 * item's own risk surcharges, which scale that same base premium.
 */
function priceMainItem(item: Item): ItemPricing {
  const basePremium = basePremiumOf(item);
  return {
    basePremium,
    riskSurcharges: riskSurchargeOf(item, basePremium),
  };
}

export function priceMainItems(mainItems: readonly Item[]): ItemPricing {
  return mainItems.reduce<ItemPricing>(
    (total, item) => combinedPricing(total, priceMainItem(item)),
    NO_PRICING,
  );
}
===== price-list.ts =====
import type { Item } from "./policy.js";

/**
 * The MHPCO price list states one row per main item type: what the item is
 * insured for, and what insuring it costs. The spec states the two figures
 * together ("Sword: 1000 G insurance value, 100 G base premium"), and the
 * MHPCO revises them together, so they are kept in one row rather than in
 * parallel tables that would have to be kept in step by hand.
 *
 * The list covers main items only. Components (runes, moonstones) are
 * priced elsewhere, by the rules that let them form blocks, so a component
 * type has no row here and this list declines to state its figures.
 */
interface PriceListRow {
  /** Unstated while no active example has yet fixed this row's figure. */
  readonly insuranceValue?: number;
  readonly basePremium?: number;
}

const MAIN_ITEM_PRICE_LIST: Readonly<Record<string, PriceListRow>> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { basePremium: 80 },
  potion: { basePremium: 40 },
};

/**
 * A figure this list does not state -- because the type has no row, or
 * because the row is silent on that figure -- costs and covers nothing.
 */
const UNSTATED = 0;

function priceListRowOf(item: Item): PriceListRow {
  return MAIN_ITEM_PRICE_LIST[item.type] ?? {};
}

/** What the MHPCO charges to insure one main item of this type, before modifiers. */
export function basePremiumOf(item: Item): number {
  return priceListRowOf(item).basePremium ?? UNSTATED;
}

/** What the MHPCO's main item price list states this type is insured for. */
export function insuranceValueOf(item: Item): number {
  return priceListRowOf(item).insuranceValue ?? UNSTATED;
}
===== item-price-rules.ts =====
import {
  COMPONENT_INSURANCE_VALUE,
  componentsBasePremium,
  isComponent,
} from "./component-price-rules.js";
import { priceMainItems } from "./main-item.js";
import type { Item } from "./policy.js";
import type { ItemPricing } from "./premium-contribution.js";
import { combinedPricing } from "./premium-contribution.js";
import { insuranceValueOf as mainItemInsuranceValueOf } from "./price-list.js";

/**
 * The MHPCO insures two kinds of thing, and each kind is governed by its own
 * price rules: main items follow the price list, components may form blocks.
 * Both of a kind's figures -- what insuring it costs and what it is insured
 * for -- come from those same rules, as the spec states them together.
 *
 * This module is the one place that decides which rules govern an item, so
 * that a new kind of insurable thing is added here and nowhere else.
 */

/**
 * Components are insured at a flat rate and carry no item-specific risk:
 * a rune has neither an enchantment level nor a material to be cursed.
 */
function priceComponents(components: readonly Item[]): ItemPricing {
  return {
    basePremium: componentsBasePremium(components),
    riskSurcharges: 0,
  };
}

/** What insuring these items costs, before policy-wide modifiers. */
export function priceItems(items: readonly Item[]): ItemPricing {
  return combinedPricing(
    priceMainItems(items.filter((item) => !isComponent(item))),
    priceComponents(items.filter(isComponent)),
  );
}

/** What the rules governing this item's kind state it is insured for. */
export function insuranceValueOf(item: Item): number {
  return isComponent(item)
    ? COMPONENT_INSURANCE_VALUE
    : mainItemInsuranceValueOf(item);
}
===== component-price-rules.ts =====
import type { Item } from "./policy.js";

/**
 * The price rules governing components such as runes and moonstones: what
 * each is insured for, and what insuring them costs -- including the
 * building block, the one concession that makes components cheaper than
 * their number alone would suggest.
 */

/** Components such as runes and moonstones share one base premium. */
const COMPONENT_BASE_PREMIUM = 25;

const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];

/**
 * Each component is insured for its own value. The building block is a
 * premium concession only: it never reduces what a component is insured for.
 */
export const COMPONENT_INSURANCE_VALUE = 250;

/** A building block of alike components is offered at a special premium. */
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

export function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

/** Components count as "alike" -- and so may form a block -- per item type. */
function alikeGroupSizes(components: readonly Item[]): readonly number[] {
  const sizes = new Map<string, number>();
  for (const component of components) {
    sizes.set(component.type, (sizes.get(component.type) ?? 0) + 1);
  }
  return [...sizes.values()];
}

/**
 * A block requires *exactly* the block size: 4 or 7 alike components are
 * priced per component, not as blocks plus a remainder.
 */
function alikeGroupBasePremium(groupSize: number): number {
  if (groupSize === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_BASE_PREMIUM;
  }
  return groupSize * COMPONENT_BASE_PREMIUM;
}

export function componentsBasePremium(components: readonly Item[]): number {
  return alikeGroupSizes(components).reduce(
    (sum, groupSize) => sum + alikeGroupBasePremium(groupSize),
    0,
  );
}
===== policy-cover.ts =====
import { insuranceValueOf } from "./item-price-rules.js";
import type { Item } from "./policy.js";

/** The policy's insurance sum is the sum of its items' insurance values. */
export function insuranceSum(items: readonly Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
}

/** The total payout per policy is capped at twice the insurance sum. */
const PAYOUT_CAP_MULTIPLE = 2;

export function payoutCap(items: readonly Item[]): number {
  return insuranceSum(items) * PAYOUT_CAP_MULTIPLE;
}
===== policy-modifier.ts =====
import type { Customer } from "./policy.js";

/**
 * Policy-wide modifiers scale the policy base premium (the sum of all item
 * base premiums). Item-specific modifiers live with the items they affect.
 *
 * Three independent policies live here, and they answer to different facts:
 * the initial assessment surcharge is a property of the quote itself, the
 * loyalty discount is a property of the customer's relationship with the
 * MHPCO, and the follow-up contract discount is a property of the
 * customer's contract history in this scenario.
 *
 * Each is expressed as a signed adjustment to the policy base premium, so
 * that a surcharge and a discount differ only in sign and the quote can sum
 * them without knowing which is which.
 */

/** Long-standing customers are rewarded with a loyalty discount. */
const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_YEARS = 2;

const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;

/** Every contract after the customer's first is discounted. */
const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;

/** What the quote is assessed against, beyond the items themselves. */
export interface Contract {
  readonly customer: Customer;
  /** Contracts this customer already holds in the scenario. */
  readonly previousContracts: number;
}

function isLongStanding(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

/** A follow-up contract is any contract after the customer's first. */
function isFollowUpContract(contract: Contract): boolean {
  return contract.previousContracts > 0;
}

/** Long-standing customers are rewarded off the premium. */
function loyaltyDiscount(contract: Contract, policyBasePremium: number): number {
  return isLongStanding(contract.customer)
    ? -policyBasePremium * LOYALTY_DISCOUNT_RATE
    : 0;
}

function followUpContractDiscount(
  contract: Contract,
  policyBasePremium: number,
): number {
  return isFollowUpContract(contract)
    ? -policyBasePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
    : 0;
}

/**
 * Every item in a quote is assessed as a first insurance, regardless of
 * customer history, so this surcharge always applies.
 */
function initialAssessmentSurcharge(policyBasePremium: number): number {
  return policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
}

/**
 * The net signed adjustment the policy-wide modifiers make to the policy
 * base premium: positive for a surcharge, negative for a discount.
 */
export function policyWideAdjustment(
  contract: Contract,
  policyBasePremium: number,
): number {
  return (
    initialAssessmentSurcharge(policyBasePremium) +
    loyaltyDiscount(contract, policyBasePremium) +
    followUpContractDiscount(contract, policyBasePremium)
  );
}
===== premium-contribution.ts =====
/**
 * What insured items contribute to a premium, before policy-wide modifiers.
 *
 * The two contributions are kept apart all the way up because policy-wide
 * modifiers scale only the policy base premium: a risk surcharge has already
 * been assessed against its own item and must not be scaled again.
 */
export interface ItemPricing {
  /** Sum of item base premiums -- the policy base premium. */
  readonly basePremium: number;
  /** Item-specific risk surcharges, each on its own item's base premium. */
  readonly riskSurcharges: number;
}

/** An item that contributes nothing -- the identity for combining pricings. */
export const NO_PRICING: ItemPricing = { basePremium: 0, riskSurcharges: 0 };

/**
 * Pricings combine by adding each contribution separately: base premiums
 * accumulate into the policy base premium, and risk surcharges accumulate
 * alongside it, because policy-wide modifiers scale only the former.
 */
export function combinedPricing(
  left: ItemPricing,
  right: ItemPricing,
): ItemPricing {
  return {
    basePremium: left.basePremium + right.basePremium,
    riskSurcharges: left.riskSurcharges + right.riskSurcharges,
  };
}
===== quote.ts =====
import { priceItems } from "./item-price-rules.js";
import type { Customer, Item } from "./policy.js";
import { policyWideAdjustment } from "./policy-modifier.js";
import { premiumRoundedInMHPCOsFavour } from "./rounding.js";

/** Every premium carries the MHPCO's flat processing fee. */
const PROCESSING_FEE = 5;

/**
 * Item-specific modifiers apply to the base premium of the affected item;
 * policy-wide modifiers apply to the policy base premium; the processing
 * fee is added at the very end, so it is part of the amount that is
 * rounded.
 *
 * Every intermediate amount stays a fraction; only this final premium is
 * stated in whole G.
 */
export function quote(
  customer: Customer,
  items: readonly Item[],
  previousContracts: number,
): number {
  const { basePremium, riskSurcharges } = priceItems(items);

  const premium =
    basePremium +
    riskSurcharges +
    policyWideAdjustment({ customer, previousContracts }, basePremium) +
    PROCESSING_FEE;

  return premiumRoundedInMHPCOsFavour(premium);
}
===== risk-surcharge.ts =====
import type { Item } from "./policy.js";

/** A cursed item adds a risk surcharge on its own base premium. */
const CURSE_SURCHARGE_RATE = 0.5;

/** Highly enchanted items add a risk surcharge on their own base premium. */
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const HIGH_ENCHANTMENT_LEVEL = 5;

function isCursed(item: Item): boolean {
  return item.cursed === true;
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function riskSurchargeRateOf(item: Item): number {
  const curseRate = isCursed(item) ? CURSE_SURCHARGE_RATE : 0;
  const enchantmentRate = isHighlyEnchanted(item)
    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0;
  return curseRate + enchantmentRate;
}

/**
 * Item-specific risk surcharges apply to the base premium of the affected
 * item, not to the policy base premium.
 */
export function riskSurchargeOf(item: Item, itemBasePremium: number): number {
  return itemBasePremium * riskSurchargeRateOf(item);
}
===== rounding.ts =====
/**
 * The MHPCO rounds every amount in its own favour, which means opposite
 * directions on the two sides of the business: a premium is what the
 * customer pays, so it rounds up.
 *
 * Only a final amount is rounded; every intermediate amount in a
 * calculation stays a fraction.
 */
export function premiumRoundedInMHPCOsFavour(premium: number): number {
  return Math.ceil(premium);
}

